<script setup>
import {ref,computed,onMounted,watch} from 'vue';
import {version as applicationVersion} from '../package.json';
import Icon from './components/Icon.vue';import BaseModal from './components/BaseModal.vue';import EmptyState from './components/EmptyState.vue';
import AssessmentsView from './views/AssessmentsView.vue';import ProsoftView from './views/ProsoftView.vue';import UsersView from './views/UsersView.vue';
import MastersView from './views/MastersView.vue';
import DashboardView from './views/DashboardView.vue';import CompaniesView from './views/CompaniesView.vue';import JournalView from './views/JournalView.vue';
import DocumentsView from './views/DocumentsView.vue';import FinanceView from './views/FinanceView.vue';import ImportView from './views/ImportView.vue';import ReconcileView from './views/ReconcileView.vue';import ReportsView from './views/ReportsView.vue';import SettingsView from './views/SettingsView.vue';import PeriodsView from './views/PeriodsView.vue';
import {state,company,api,refreshSession,activate,notify,answer,ask} from './lib/workspace';import {taxId,normalized} from './lib/format';
const menus=[{id:'dashboard',label:'Visão geral',icon:'dashboard',component:DashboardView},{id:'companies',label:'Empresas',icon:'building',component:CompaniesView},{id:'masters',label:'Cadastros auxiliares',icon:'building',component:MastersView},{id:'documents',label:'Documentos fiscais',icon:'documents',component:DocumentsView},{id:'imports',label:'Importações',icon:'import',component:ImportView},{id:'journal',label:'Contabilidade',icon:'journal',component:JournalView},{id:'finance',label:'Financeiro',icon:'finance',component:FinanceView},{id:'reconcile',label:'Conciliação',icon:'reconcile',component:ReconcileView},{id:'reports',label:'Livros e relatórios',icon:'reports',component:ReportsView},{id:'settings',label:'Parâmetros',icon:'settings',component:SettingsView},{id:'assessments',label:'Pré-apuração fiscal',icon:'reports',component:AssessmentsView},{id:'prosoft',label:'Integração Prosoft',icon:'import',component:ProsoftView},{id:'users',label:'Usuários e acessos',icon:'shield',component:UsersView},{id:'periods',label:'Competências',icon:'periods',component:PeriodsView}];
const openTabs=ref(['dashboard']),mobileMenu=ref(false),search=ref(''),searchOpen=ref(false),confirmInput=ref('');
const current=computed(()=>menus.find(x=>x.id===state.tab)||menus[0]);const filteredMenu=computed(()=>menus.filter(x=>normalized(x.label).includes(normalized(search.value))));const filteredCompanies=computed(()=>state.companies.filter(x=>normalized(`${x.code} ${x.name} ${x.tax_id}`).includes(normalized(search.value))));
const login=ref({username:'',password:''}),loginError=ref(''),loginBusy=ref(false);
watch(()=>state.tab,id=>{if(!openTabs.value.includes(id))openTabs.value.push(id);mobileMenu.value=false;});watch(()=>state.confirm,()=>{confirmInput.value='';});
async function initialize(){try{await refreshSession();if(!state.companyId&&state.session?.authenticated)state.tab='companies';}catch(e){loginError.value=e.message;state.loading=false;}}
onMounted(initialize);
function navigate(id){if(state.editor){notify('Feche a janela em edição para navegar para outra guia.','warning');return;}state.tab=id;searchOpen.value=false;}
function closeTab(id){if(openTabs.value.length===1||state.editor)return;const ix=openTabs.value.indexOf(id);openTabs.value.splice(ix,1);if(state.tab===id)state.tab=openTabs.value[Math.max(0,ix-1)];}
async function contextChange(id,p=state.period){try{await activate(Number(id),p);}catch(e){notify(e.message,'error');}}
async function periodChange(event){const m=/^(0[1-9]|1[0-2])\/(\d{4})$/.exec(event.target.value);if(!m){notify('Informe a competência no formato MM/AAAA.','warning');event.target.value=state.period.split('-').reverse().join('/');return;}await contextChange(state.companyId,`${m[2]}-${m[1]}`);event.target.value=state.period.split('-').reverse().join('/');}
async function signIn(demo=false){loginBusy.value=true;loginError.value='';try{await api(demo?'/demo-login':state.session?.setup_required?'/setup':'/login',{method:'POST',body:demo?{}:login.value});await initialize();login.value.password='';}catch(e){loginError.value=e.message;}finally{loginBusy.value=false;}}
async function signOut(){if(state.editor)return;await api('/logout',{method:'POST',body:{}});state.companyId=null;state.companies=[];await initialize();}
async function chooseSearchCompany(c){searchOpen.value=false;await contextChange(c.id);}
function confirmAction(){if(state.confirm.required&&!confirmInput.value.trim())return;answer(state.confirm.inputLabel?confirmInput.value.trim():true);}
</script>
<template><div v-if="state.loading" class="boot-screen"><img src="/brand.svg" alt=""/><h1>Escritura Integrada</h1><p><Icon name="loading"/>Preparando seu espaço de trabalho...</p></div>
<div v-else-if="!state.session?.authenticated" class="login-page"><section class="login-intro"><div class="brand"><img src="/brand.svg" alt=""/><div><strong>Escritura</strong><span>INTEGRADA</span></div></div><span class="eyebrow">CODISPLAN · ESCRITÓRIO CONECTADO</span><h1>Uma empresa.<br>Todo o contexto.</h1><p>Documentos, escrituração e financeiro no mesmo espaço de trabalho. Cada registro com origem, conferência e rastreabilidade.</p><div class="login-points"><span><Icon name="building"/>Empresa sempre identificada</span><span><Icon name="layers"/>Fiscal, contábil e financeiro</span><span><Icon name="shield"/>Histórico e competências protegidos</span></div><small>Escritura Integrada · {{applicationVersion}}</small></section><section class="login-card"><h2>{{state.session?.setup_required?'Prepare seu escritório':'Acesse seu escritório'}}</h2><p>{{state.session?.setup_required?'Crie o responsável pelo ambiente. Seus dados serão armazenados nesta instalação.':'Informe suas credenciais para continuar.'}}</p><div v-if="loginError" class="message error" role="alert">{{loginError}}</div><form @submit.prevent="signIn(false)"><label>Usuário<input v-model="login.username" autocomplete="username" required autofocus placeholder="Seu usuário"/></label><label>Senha<input v-model="login.password" type="password" :autocomplete="state.session?.setup_required?'new-password':'current-password'" required :minlength="state.session?.setup_required?12:1" placeholder="Sua senha"/><small v-if="state.session?.setup_required">Use pelo menos 12 caracteres.</small></label><button class="button primary full" :disabled="loginBusy"><Icon v-if="loginBusy" name="loading"/>{{state.session?.setup_required?'Criar acesso e continuar':'Entrar'}}<Icon name="arrow"/></button></form><div v-if="state.session?.demo" class="demo-login"><span>Conheça os fluxos com dados fictícios</span><button class="button outline full" @click="signIn(true)" :disabled="loginBusy">Entrar na demonstração<Icon name="arrow"/></button></div></section></div>
<div v-else class="app-shell"><aside class="sidebar" :class="{visible:mobileMenu}"><div class="brand"><img src="/brand.svg" alt=""/><div><strong>Escritura</strong><span>INTEGRADA</span></div><button class="icon-button mobile-only" @click="mobileMenu=false" aria-label="Fechar navegação"><Icon name="close"/></button></div><div class="nav-label">ESPAÇO DE TRABALHO</div><nav aria-label="Navegação principal"><button v-for="m in menus.filter(m=>m.id!=='users'||state.session?.user?.role==='admin')" :key="m.id" :class="{selected:state.tab===m.id}" @click="navigate(m.id)"><Icon :name="m.icon"/><span>{{m.label}}</span><span v-if="state.tab===m.id" class="nav-indicator"></span></button></nav><div class="sidebar-bottom"><div class="office-sign"><span class="office-monogram">C</span><div><strong>Codisplan</strong><small>Gestão do escritório</small></div></div><div class="connection"><span class="dot green"></span><span>Conectado</span><small>{{applicationVersion}}</small></div></div></aside><div v-if="mobileMenu" class="sidebar-scrim" @click="mobileMenu=false"></div>
<div class="workspace"><header class="topbar"><button class="icon-button mobile-only" @click="mobileMenu=true" aria-label="Abrir navegação"><Icon name="menu"/></button><div class="company-switch"><span class="company-switch-icon"><Icon name="building" :size="21"/></span><div><label for="active-company">EMPRESA ATIVA</label><select id="active-company" :value="state.companyId||''" :disabled="state.contextBusy||!!state.editor" @change="contextChange($event.target.value)"><option value="" disabled>Selecione uma empresa</option><option v-for="c in state.companies" :key="c.id" :value="c.id">{{c.code}} · {{c.trade_name||c.name}}</option></select><small>{{company?taxId(company.tax_id):'Cadastre ou ative uma empresa para começar'}}</small></div></div><div class="period-picker"><label for="active-period">COMPETÊNCIA</label><input id="active-period" type="text" inputmode="numeric" maxlength="7" placeholder="MM/AAAA" :value="state.period.split('-').reverse().join('/')" :disabled="!state.companyId||state.contextBusy||!!state.editor" @change="periodChange"/></div><button class="global-search" @click="search='';searchOpen=true" aria-label="Buscar módulo ou empresa"><Icon name="search"/><span>Buscar no escritório</span><kbd>⌕</kbd></button><div class="user-menu"><span class="user-avatar">{{(state.session.user?.username||state.session.user?.name||'C').slice(0,1).toUpperCase()}}</span><span>{{state.session.user?.username||state.session.user?.name||'Operador'}}</span><button class="icon-button" @click="signOut" aria-label="Sair da aplicação" title="Sair"><Icon name="logout" :size="17"/></button></div></header>
<div v-if="state.session.demo" class="demo-banner"><Icon name="info" :size="14"/><span>Ambiente de demonstração · dados fictícios</span><span>Faça os testes sem usar documentos reais.</span></div>
<div class="workspace-tabs" role="tablist" aria-label="Guias abertas"><div v-for="id in openTabs" :key="id" class="workspace-tab" :class="{selected:state.tab===id}"><button role="tab" :aria-selected="state.tab===id" @click="navigate(id)"><Icon :name="menus.find(m=>m.id===id)?.icon" :size="15"/>{{menus.find(m=>m.id===id)?.label}}</button><button v-if="openTabs.length>1" class="tab-close" @click="closeTab(id)" :aria-label="`Fechar guia ${menus.find(m=>m.id===id)?.label}`"><Icon name="close" :size="13"/></button></div><span class="tabs-spacer"></span><div v-if="state.companyId" class="context-locks"><span :title="`Fiscal ${state.locks.fiscal?.closed?'fechado':'aberto'}`"><span class="dot" :class="state.locks.fiscal?.closed?'amber':'green'"></span>Fiscal</span><span :title="`Contábil ${state.locks.accounting?.closed?'fechado':'aberto'}`"><span class="dot" :class="state.locks.accounting?.closed?'amber':'green'"></span>Contábil</span></div></div>
<main class="main-content"><EmptyState v-if="!state.companyId&&state.tab!=='companies'" title="Escolha a empresa de trabalho" text="Ative uma empresa para acessar seus documentos, lançamentos e relatórios." icon="building"><button class="button primary" @click="navigate('companies')">Abrir empresas<Icon name="arrow"/></button></EmptyState><KeepAlive v-else><component :is="current.component" :key="state.tab"/></KeepAlive></main></div></div>
<BaseModal v-if="state.confirm" :title="state.confirm.title" narrow @close="answer(false)"><p class="confirm-message">{{state.confirm.message}}</p><label v-if="state.confirm.inputLabel">{{state.confirm.inputLabel}}<textarea v-model="confirmInput" rows="3" :required="state.confirm.required" autofocus/></label><template #footer><button class="button" @click="answer(false)">Voltar</button><button class="button" :class="state.confirm.danger?'danger':'primary'" :disabled="state.confirm.required&&!confirmInput.trim()" @click="confirmAction">{{state.confirm.confirmLabel}}</button></template></BaseModal>
<BaseModal v-if="searchOpen" title="Buscar no escritório" narrow @close="searchOpen=false"><div class="search-field"><Icon name="search"/><input v-model="search" placeholder="Módulo, empresa ou CNPJ" autofocus/></div><div class="search-results"><small>MÓDULOS</small><button v-for="m in filteredMenu" :key="m.id" @click="navigate(m.id)"><Icon :name="m.icon"/><span>{{m.label}}</span><Icon name="arrow" :size="15"/></button><small v-if="filteredCompanies.length">EMPRESAS</small><button v-for="c in filteredCompanies.slice(0,6)" :key="c.id" @click="chooseSearchCompany(c)"><Icon name="building"/><span>{{c.code}} · {{c.trade_name||c.name}}</span><span v-if="c.id===state.companyId" class="badge success">Ativa</span></button></div></BaseModal>
<div class="toast-stack" aria-live="polite"><div v-for="t in state.toasts" :key="t.id" class="toast" :class="t.type" role="status"><Icon :name="t.type==='success'?'check':'alert'"/><span>{{t.message}}</span><button class="icon-button" @click="state.toasts=state.toasts.filter(x=>x.id!==t.id)" aria-label="Fechar aviso"><Icon name="close" :size="14"/></button></div></div>
</template>
